"""PRISMtrace client for AI observability."""
from __future__ import annotations


import atexit
import json
import sys
import threading
import uuid
import weakref
from functools import wraps
from typing import Any, Callable, Optional, List

import httpx

from ._session import resolve_session

# Weak refs so atexit can drain in-flight posts without keeping every client
# alive for the life of the process. ``atexit.register(self.flush)`` held a
# strong reference to each instance, so a client was never collected and its
# connection pool never released.
_LIVE_CLIENTS: "weakref.WeakSet[PRISMtrace]" = weakref.WeakSet()
_ATEXIT_REGISTERED = False


def _register_atexit() -> None:
    global _ATEXIT_REGISTERED
    if _ATEXIT_REGISTERED:
        return

    def _flush_all() -> None:
        for client in list(_LIVE_CLIENTS):
            try:
                client.flush()
            except Exception:
                pass

    atexit.register(_flush_all)
    _ATEXIT_REGISTERED = True


class PRISMtrace:
    def __init__(
        self,
        api_key: str,
        host: str,
        project_id: str,
        timeout: int = 10,
    ):
        self.api_key = api_key
        self.host = host.rstrip("/")
        self.project_id = project_id
        self.timeout = timeout
        self._client = httpx.Client(
            base_url=self.host,
            headers={
                "x-prismtrace-key": api_key,
                "Content-Type": "application/json",
            },
            timeout=self.timeout,
        )
        # Track in-flight background threads so we can flush them on exit
        self._pending_threads: List[threading.Thread] = []
        self._threads_lock = threading.Lock()
        self._closed = False
        _LIVE_CLIENTS.add(self)
        _register_atexit()

    # ------------------------------------------------------------------
    # Traces (existing)
    # ------------------------------------------------------------------

    def trace_llm(
        self,
        model: str,
        input_messages: list,
        output: str,
        latency_ms: int,
        token_count_input: int = 0,
        token_count_output: int = 0,
        trace_id: Optional[str] = None,
        agent_id: Optional[str] = None,
        agent_name: Optional[str] = None,
        session_id: Optional[str] = None,
        metadata: Optional[dict] = None,
    ) -> None:
        """Record one LLM call.

        ``agent_id`` is the stable identity of the agent making the call and
        ``agent_name`` is its human label. Pass an id you mint once and never
        change — it is what guardrail and alert rules scope to, so changing it
        makes the platform treat this as a different agent.

        Both were previously only expressible by hand-writing keys into
        ``metadata``, which is why callers disagreed about the spelling and
        some agents ended up identified by their display name. Passing them
        via metadata still works and means the same thing.

        ``session_id`` is what groups several calls into one conversation. It
        had no parameter at all, so the only way to express it was a hand-written
        metadata key; left out, the ambient session is used when one is open.
        """
        payload = {
            "project_id": self.project_id,
            "model": model,
            "input_messages": input_messages,
            "output_message": output,
            "latency_ms": latency_ms,
            "token_count_input": token_count_input,
            "token_count_output": token_count_output,
        }
        if trace_id is not None:
            payload["trace_id"] = trace_id
        if agent_id is not None:
            payload["agent_id"] = agent_id
        if agent_name is not None:
            payload["agent_name"] = agent_name
        if metadata is not None:
            payload["metadata"] = metadata
        resolved_session = session_id or (metadata or {}).get("session_id")
        resolved_session = resolve_session(resolved_session, "")
        if resolved_session:
            payload["session_id"] = resolved_session

        # Create a non-daemon thread so we can track and join it later
        thread = threading.Thread(
            target=self._post,
            args=("/api/traces", payload),
            daemon=False,
        )
        with self._threads_lock:
            self._pending_threads.append(thread)
        thread.start()

    def _post(self, path: str, payload: dict) -> Optional[dict]:
        try:
            resp = self._client.post(path, json=payload)
            if resp.status_code in (200, 201):
                return resp.json()
            print(
                f"PRISMtrace warning: {path} returned {resp.status_code}: {resp.text[:200]}",
                file=sys.stderr,
            )
        except Exception as e:
            print(f"PRISMtrace warning: {path} failed: {e}", file=sys.stderr)
        return None

    def _post_sync(self, path: str, payload: dict) -> Optional[dict]:
        try:
            resp = self._client.post(path, json=payload)
            if resp.status_code in (200, 201):
                return resp.json()
            print(
                f"PRISMtrace warning: {path} returned {resp.status_code}: {resp.text[:200]}",
                file=sys.stderr,
            )
        except Exception as e:
            print(f"PRISMtrace warning: {path} failed: {e}", file=sys.stderr)
        return None

    def _get_sync(self, path: str) -> Optional[dict]:
        try:
            resp = self._client.get(path)
            if resp.status_code == 200:
                return resp.json()
            print(
                f"PRISMtrace warning: GET {path} returned {resp.status_code}: {resp.text[:200]}",
                file=sys.stderr,
            )
        except Exception as e:
            print(f"PRISMtrace warning: GET {path} failed: {e}", file=sys.stderr)
        return None

    def trace(self, name: Optional[str] = None) -> Callable:
        def decorator(fn: Callable) -> Callable:
            @wraps(fn)
            def wrapper(*args: Any, **kwargs: Any) -> Any:
                import time
                start = time.perf_counter()
                result = fn(*args, **kwargs)
                elapsed_ms = int((time.perf_counter() - start) * 1000)
                self.trace_llm(
                    model=name or fn.__name__,
                    input_messages=[{"role": "user", "content": str(args)}],
                    output=str(result),
                    latency_ms=elapsed_ms,
                )
                return result
            return wrapper
        return decorator

    # ------------------------------------------------------------------
    # Trajectories
    # ------------------------------------------------------------------

    def submit_trajectory(
        self,
        steps: list[dict],
        *,
        agent_name: str = "default-agent",
        agent_id: Optional[str] = None,
        conversation_id: Optional[str] = None,
        request_id: Optional[str] = None,
        model: Optional[str] = None,
        final_status: str = "success",
        async_send: bool = False,
    ) -> Optional[dict]:
        """Submit a trajectory (ordered step list) for PRISM evaluation.

        Each step dict should contain:
            step_type:       "reasoning" | "tool_call" | "final_answer" | ...
            label:           short description
            output_summary:  what this step produced (optional but recommended)
            tool_name:       tool identifier (required when step_type is tool_call)
            input_summary:   what went in (optional)
            duration_ms:     step latency (optional)
            token_count:     tokens used (optional)
            status:          "success" | "error" (default "success")

        Returns the API response dict (trajectory id, step_count, created_at)
        or None on failure.
        """
        payload = {
            "project_id": self.project_id,
            # The ambient session, when one is open, is the same grouping key
            # a trajectory calls conversation_id.
            "conversation_id": resolve_session(conversation_id, str(uuid.uuid4())),
            "request_id": request_id or str(uuid.uuid4()),
            # Falling back to the display name makes the NAME the identity,
            # so renaming the agent creates a new one and every rule scoped to
            # the old name goes inert. Kept for compatibility — changing it
            # would re-identify every agent already relying on it — but pass
            # an explicit agent_id and the name becomes free to change.
            # The server records the fallback key as an alias, so an agent
            # that later starts sending a real id merges instead of forking.
            "agent_id": agent_id or agent_name,
            "agent_name": agent_name,
            "steps": steps,
            "total_duration_ms": sum(s.get("duration_ms") or 0 for s in steps),
            "final_status": final_status,
            "model": model,
        }
        if async_send:
            # Non-daemon thread so we can track it
            thread = threading.Thread(
                target=self._post,
                args=("/api/trajectories", payload),
                daemon=False,
            )
            with self._threads_lock:
                self._pending_threads.append(thread)
            thread.start()
            return None
        return self._post_sync("/api/trajectories", payload)

    def flush(self, timeout: float = 2.0) -> None:
        """Wait for all pending background requests to complete.

        This is called automatically at exit, but you can call it explicitly
        before your script ends to ensure traces are sent.
        """
        # Copy the list so we can work without holding the lock for long
        with self._threads_lock:
            threads = self._pending_threads[:]
            self._pending_threads.clear()

        for t in threads:
            if t.is_alive():
                t.join(timeout)
                if t.is_alive():
                    # Log that we couldn't finish in time
                    print(
                        "PRISMtrace warning: background request did not finish within timeout",
                        file=sys.stderr,
                    )

    def close(self) -> None:
        """Drain in-flight posts, then release the HTTP connection pool.

        Idempotent. Also available as a context manager.
        """
        if self._closed:
            return
        self._closed = True
        try:
            self.flush()
        finally:
            try:
                self._client.close()
            except Exception:
                pass
            _LIVE_CLIENTS.discard(self)

    def __enter__(self) -> "PRISMtrace":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.close()
        return False

    def get_trajectory(self, trajectory_id: str) -> Optional[dict]:
        """Fetch a trajectory and its steps."""
        return self._get_sync(f"/api/trajectories/{trajectory_id}")

    def get_trajectory_evaluation(self, trajectory_id: str) -> Optional[dict]:
        """Fetch PRISM evaluation results for a trajectory."""
        return self._get_sync(f"/api/trajectories/{trajectory_id}/evaluation")

    def retrigger_evaluation(self, trajectory_id: str) -> Optional[dict]:
        """Re-run PRISM evaluation for an existing trajectory."""
        return self._post_sync(
            f"/api/trajectories/{trajectory_id}/evaluate?project_id={self.project_id}",
            {},
        )

    # ------------------------------------------------------------------
    # Knowledge Base
    # ------------------------------------------------------------------

    def kb_upload(
        self,
        filename: str,
        content: bytes | str,
        *,
        agent_id: Optional[str] = None,
        description: Optional[str] = None,
        content_type: str = "text/plain",
    ) -> Optional[dict]:
        """Upload a document to the project knowledge base.

        Returns {"id", "name", "chunk_count", ...} or None on failure.
        """
        if isinstance(content, str):
            content = content.encode("utf-8")

        files = {"file": (filename, content, content_type)}
        data: dict[str, str] = {"project_id": self.project_id}
        if agent_id:
            data["agent_id"] = agent_id
        if description:
            data["description"] = description

        try:
            resp = httpx.post(
                f"{self.host}/api/knowledge-base/documents",
                files=files,
                data=data,
                headers={"x-prismtrace-key": self.api_key},
                timeout=self.timeout,
            )
            if resp.status_code in (200, 201):
                return resp.json()
            print(f"PRISMtrace warning: kb_upload returned {resp.status_code}")
        except Exception as e:
            print(f"PRISMtrace warning: kb_upload failed: {e}")
        return None

    def kb_search(
        self,
        query: str,
        *,
        agent_id: Optional[str] = None,
        limit: int = 5,
    ) -> list[dict]:
        """Search the project knowledge base. Returns list of chunk results."""
        payload: dict[str, Any] = {
            "query": query,
            "project_id": self.project_id,
            "limit": limit,
        }
        if agent_id:
            payload["agent_id"] = agent_id
        result = self._post_sync("/api/knowledge-base/search", payload)
        if result:
            return result.get("results", [])
        return []

    def kb_list_documents(self, agent_id: Optional[str] = None) -> list[dict]:
        """List documents in the project knowledge base."""
        path = f"/api/knowledge-base/documents?project_id={self.project_id}"
        if agent_id:
            path += f"&agent_id={agent_id}"
        result = self._get_sync(path)
        if result:
            return result.get("documents", [])
        return []

    def kb_delete_document(self, doc_id: str) -> bool:
        """Delete a document from the knowledge base."""
        try:
            resp = self._client.delete(
                f"/api/knowledge-base/documents/{doc_id}?project_id={self.project_id}",
            )
            return resp.status_code == 200
        except Exception:
            return False